+    "bifrostTaskRole",
+    {
+      name: TASK_ROLE_NAME,
+      description:
+        "Bifrost gateway task: invoke the models in utils/bedrock-models.ts and nothing else.",
+      assumeRolePolicy: pulumi.jsonStringify({
+        Version: "2012-10-17",
+        Statement: [
+          {
+            Effect: "Allow",
+            Action: "sts:AssumeRole",
+            Principal: { Service: "ecs-tasks.amazonaws.com" },
+          },
+        ],
+      }),
+      inlinePolicies: [
+        {
